SELECT i.* FROM edu_idiom i INNER JOIN edu_idiom_grade g ON i.idiom_id = g.idiom_id WHERE g.grade_level = #{gradeLevel}
AND (g.grade IS NULL OR g.grade = #{grade})
AND (i.idiom_owner_user_id IS NULL OR i.idiom_owner_user_id = #{userId})
ORDER BY RAND() LIMIT #{count}

